create table if not exists public.official_profiles (slug text primary key,display_name text not null,handle text not null unique,role text not null,city text,state text,avatar_url text,bio text,created_at timestamptz not null default now());
create table if not exists public.official_follows (profile_slug text not null references public.official_profiles(slug) on delete cascade,user_id uuid not null references auth.users(id) on delete cascade,created_at timestamptz not null default now(),primary key(profile_slug,user_id));
create table if not exists public.official_tracks (id uuid primary key default gen_random_uuid(),profile_slug text not null references public.official_profiles(slug) on delete cascade,title text not null,audio_url text,cover_url text,play_count bigint not null default 0 check(play_count>=0),published boolean not null default false,created_at timestamptz not null default now());
insert into public.official_profiles(slug,display_name,handle,role,city,state,avatar_url,bio) values('ejaypapi','EJAY PAPI','@ejaypapi','Host','Orlando','FL','https://the-merge-music.lovable.app/__l5e/assets-v1/d466471d-69af-4352-b755-cf5f69b4dde3/ejay-papi-host.png','Official host of The Merge—real conversations, music and community connections.') on conflict(slug) do update set display_name=excluded.display_name,handle=excluded.handle,role=excluded.role,city=excluded.city,state=excluded.state,avatar_url=excluded.avatar_url,bio=excluded.bio;
alter table public.official_profiles enable row level security;alter table public.official_follows enable row level security;alter table public.official_tracks enable row level security;
create policy "members read official profiles" on public.official_profiles for select to authenticated using(true);
create policy "members read published tracks" on public.official_tracks for select to authenticated using(published=true or public.is_staff());
create policy "members read follows" on public.official_follows for select to authenticated using(true);
create policy "members follow as themselves" on public.official_follows for insert to authenticated with check(user_id=auth.uid());
create policy "members unfollow as themselves" on public.official_follows for delete to authenticated using(user_id=auth.uid());
